const revokeCredential = `-- name: RevokeCredential :one
UPDATE mod_users.credentials
SET revoked_at = now(),
    revoke_reason = $2
WHERE id = $1 AND revoked_at IS NULL
RETURNING id, uuid, principal_id, kind, confined_to_party_id, default_profile_id, expires_at, label, revoke_reason, revoked_at, created_at, created_by_profile_id, last_used_at
`

type RevokeCredentialParams struct {
	ID           int64       `json:"id"`
	RevokeReason pgtype.Text `json:"revoke_reason"`
}

// Idempotent guard: only an unrevoked credential is revoked (no row otherwise).
func (q *Queries) RevokeCredential(ctx context.Context, arg RevokeCredentialParams) (Credential, error) {
	row := q.db.QueryRow(ctx, revokeCredential, arg.ID, arg.RevokeReason)
	var i Credential
	err := row.Scan(
		&i.ID,
		&i.Uuid,
		&i.PrincipalID,
		&i.Kind,
		&i.ConfinedToPartyID,
		&i.DefaultProfileID,
		&i.ExpiresAt,
		&i.Label,
		&i.RevokeReason,
		&i.RevokedAt,
		&i.CreatedAt,
		&i.CreatedByProfileID,
		&i.LastUsedAt,
	)
	return i, err
}

const revokeSessionsHoldingCredential = `-- name: RevokeSessionsHoldingCredential :many
UPDATE mod_users.sessions
SET revoked_at = now(),
    revoke_reason = 'credential_revoked'
WHERE revoked_at IS NULL
  AND id IN (
      SELECT f.session_id
      FROM mod_users.session_factors f
      WHERE f.credential_id = $1
  )
RETURNING id, uuid, principal_id, app_id, impersonated_profile_id, impersonator_session_id, acr, amr, auth_time, impersonation_reason, revoke_reason, revoked_at, created_at, expires_at, last_seen_at
`

// Revoke every unrevoked session holding the credential as a factor
// (revoke_reason 'credential_revoked'). Impersonation children end through
// session_liveness (parent_session_ended). Returns the revoked sessions.
func (q *Queries) RevokeSessionsHoldingCredential(ctx context.Context, credentialID int64) ([]Session, error) {
	rows, err := q.db.Query(ctx, revokeSessionsHoldingCredential, credentialID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Session
	for rows.Next() {
		var i Session
		if err := rows.Scan(
			&i.ID,
			&i.Uuid,
			&i.PrincipalID,
			&i.AppID,
			&i.ImpersonatedProfileID,
			&i.ImpersonatorSessionID,
			&i.Acr,
			&i.Amr,
			&i.AuthTime,
			&i.ImpersonationReason,
			&i.RevokeReason,
			&i.RevokedAt,
			&i.CreatedAt,
			&i.ExpiresAt,
			&i.LastSeenAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

